-- ===== Facts (24) =====
('fertile', 'fact', 'Welcome fertile window', 'Sperma bisa survive 5 hari di tubuh. Ditambah egg viable 24h saat ovulasi = 6-day window konsepsi.', '🪟', 1),
('fertile', 'fact', 'Cervical mucus = key sign', 'Mucus jadi kayak putih telur (egg-white): bening, stretchy, slippery. Sign body siap konsepsi.', '🥚', 2),
('fertile', 'fact', 'Cervix position changes', 'Cervix naik lebih tinggi, jadi softer + lebih open. Kalau lo cek manual, beda jelas dari hari biasa.', '🔝', 3),
('fertile', 'fact', 'BBT belum naik', 'Basal body temperature masih low di fertile window pre-ovulasi. Naik baru SETELAH ovulasi.', '🌡️', 4),
('fertile', 'fact', 'LH starting to rise', 'Luteinizing hormone mulai naik 24-36 jam sebelum ovulasi. LH test strip jadi positif.', '📈', 5),
('fertile', 'fact', 'Estrogen peak', 'Estrogen reach peak ~1 hari sebelum ovulasi. Inilah yang trigger LH surge.', '⛰️', 6),
('fertile', 'fact', 'Libido natural rise', 'Hormonal cocktail di fertile = libido naik biological. Bukan accidental — body ngajak reproductive activity.', '💕', 7),
('fertile', 'fact', 'Ovulation pain (mittelschmerz)', '15-20% orang feel sakit ringan di sisi ovarium yang ovulate. Sharp twinge atau dull ache, beberapa jam.', '⚡', 8),
('fertile', 'fact', 'Skin glow peak', 'Estrogen + progesteron balance + circulation up = banyak orang look "best skin" di fertile window.', '✨', 9),
('fertile', 'fact', 'Conception probability', 'Hari -2 sebelum ovulasi = 33% chance konsepsi (puncak). Hari ovulasi = 27%. Drop drastis after.', '📊', 10),
('fertile', 'fact', 'Sperm survival 5 days', 'Sperma di cervical mucus fertile bisa survive 5 hari. Itu kenapa fertile window mulai 5 hari sebelum ovulasi.', '🏊', 11),
('fertile', 'fact', 'Egg = single shot', 'Egg viable cuma 12-24 jam after release. Sperma bisa nunggu, egg gak bisa.', '⏰', 12),
('fertile', 'fact', 'Voice subtle higher', 'Studi 2008 (Bryant): perempuan suara sedikit lebih tinggi di fertile window. Subliminal signal.', '🎤', 13),
('fertile', 'fact', 'Smell more sensitive', 'Estrogen amplify smell perception. Banyak laporan "everything smells stronger" di fertile.', '👃', 14),
('fertile', 'fact', 'Attractiveness studies', 'Studi multiple (Roberts 2004, Haselton 2007): perempuan rated more attractive di fertile by laki-laki blind to cycle phase.', '🌹', 15),
('fertile', 'fact', 'Risk-taking down', 'Counterintuitive — risk-taking sebenarnya turun di fertile (Bröder 2003). Caution mode subconscious.', '🛡️', 16),
('fertile', 'fact', 'Body awareness peaks', 'Kinesthetic awareness lebih tinggi. Banyak yang feel "in tune with body" specifically saat fertile.', '🧘‍♀️', 17),
('fertile', 'fact', 'Saliva ferning', 'Saliva di-dry on glass + microscope = pattern ferning saat estrogen tinggi. Fertility tracker hack.', '🔬', 18),
('fertile', 'fact', 'Sleep deeper', 'Pre-ovulation BBT low + serotonin balanced = deep sleep more accessible.', '🌙', 19),
('fertile', 'fact', 'Cervix soft like lips', 'Pre-fertile: firm kayak hidung. Fertile: soft kayak bibir. Tactile sign signifikan.', '👄', 20),
('fertile', 'fact', 'Spinnbarkeit test', 'Tarik mucus antara 2 jari. Stretchy 5-10 cm tanpa putus = peak fertility. Sebutan resmi: spinnbarkeit.', '📏', 21),
('fertile', 'fact', 'Conception beyond fertile', 'Walaupun fertile window 6 hari, konsepsi paling probable di hari -1 + 0 (ovulation day). Sperm + egg both fresh.', '🎯', 22),
('fertile', 'fact', 'Energy still high', 'Estrogen tinggi = energy carry-over dari follicular. Workouts + projects masih flowing.', '⚡', 23),
('fertile', 'fact', 'Why "fertile" matters tracking', 'Even kalau gak planning konsepsi, knowing window = empowerment. Body literacy = self-care foundation.', '📚', 24),

-- ===== Tips (20) =====
('fertile', 'tip', 'Cek mucus pas mandi', 'Bilas dengan tissue pas pup, atau jari saat shower. Wet, slippery, stretchy = peak.', '🚿', 30),
('fertile', 'tip', 'BBT measurement consistency', 'Ukur saat bangun tidur SEBELUM gerak, jam yang sama. Pre-ovulasi steady, post jelas naik.', '🌡️', 31),
('fertile', 'tip', 'LH strip morning + sore', 'LH surge 24-36 jam. Tes 2x sehari tangkap timing optimal kalau planning konsepsi.', '🧪', 32),
('fertile', 'tip', 'Folate kalau planning konsepsi', '400 mcg folate harian, mulai 3 bulan sebelum konsepsi. Reduce neural tube defect risk dramatically.', '🥬', 33),
('fertile', 'tip', 'Avoid alkohol kalau trying', 'Alkohol pengaruhi sperm quality (kalau partner male) + egg quality. Cut atau minimize at fertile.', '🚫', 34),
